26	 * sent itself.
27	 */
28	@Component
29	public class AlbHeaderTrust {
30	
31	    private final DeviceLogsProperties.Trust names;
32	
33	    public AlbHeaderTrust(DeviceLogsProperties properties) {
34	        this.names = properties.trust();
35	    }
36	
37	    /**
38	     * @throws UntrustedIdentityException if a certificate header is missing or repeated, the leaf does not parse, its
39	     *                                    CN is not 12 uppercase hex digits or differs from the Subject header, or
40	     *                                    X-Forwarded-For has no last entry
41	     */
42	    public ClientIdentity identify(HttpHeaders headers) {
43	        String subject = exactlyOnce(headers, names.subject());
44	        exactlyOnce(headers, names.issuer());
45	        exactlyOnce(headers, names.validity());
46	        exactlyOnce(headers, names.serialNumber());
47	        X509Certificate leaf = parseLeaf(exactlyOnce(headers, names.leaf()));
48	
49	        String leafCn = commonName(leaf.getSubjectX500Principal().getName(X500Principal.RFC2253), "leaf certificate");
50	        // Check: the CN is 12 hex digits, all uppercase, as the phone certificates are issued.
51	        MacAddress mac = MacAddress.parse(leafCn)
52	                .filter(parsed -> parsed.uppercase().equals(leafCn))
53	                .orElseThrow(() -> new UntrustedIdentityException("leaf certificate CN is not 12 uppercase hex digits"));
54	        // Check: the Subject header and the leaf are two copies of the same name, so their CNs must agree.
55	        if (!leafCn.equals(commonName(subject, "Subject header"))) {
56	            throw new UntrustedIdentityException("leaf certificate CN differs from the Subject header CN");
57	        }
58	        return new ClientIdentity(mac, serial(leaf), lastForwardedFor(headers));
59	    }
60	
61	    // HttpHeaders keeps one entry per header line and does not split on commas, which matters because a Subject
62	    // holds commas.
63	    private static String exactlyOnce(HttpHeaders headers, String name) {
64	        List<String> values = headers.getOrEmpty(name);
65	        // Check: zero copies or two copies both fail, because we can't tell which copy the ALB wrote.
66	        if (values.size() != 1) {
67	            throw new UntrustedIdentityException(name + " appears " + values.size() + " times, expected once");
68	        }
69	        return values.get(0);
70	    }
71	
