73	    // also copes with an ALB that does encode it.
74	    private static X509Certificate parseLeaf(String urlEncodedPem) {
75	        try {
76	            // Check: the decoded text must be an X.509 certificate. The ALB already checked trust and expiry during the
77	            // handshake, so this only turns the text back into a certificate.
78	            String pem = URLDecoder.decode(urlEncodedPem.replace("+", "%2B"), StandardCharsets.UTF_8);
