89	            List<String> cns = new LdapName(rfc2253).getRdns().stream()
90	                    .filter(rdn -> rdn.getType().equalsIgnoreCase("CN"))
91	                    .map(rdn -> rdn.getValue().toString())
92	                    .toList();
