94	            if (cns.size() != 1) {
95	                throw new UntrustedIdentityException(source + " has " + cns.size() + " CNs, expected one");
96	            }
97	            return cns.get(0);
98	        } catch (InvalidNameException ignored) {
99	            // No cause: its message repeats the whole name, which comes from the client.
100	            throw new UntrustedIdentityException(source + " is not an RFC 2253 name");
101	        }
102	    }
