105	    private static String serial(X509Certificate leaf) {
106	        String hex = leaf.getSerialNumber().toString(16).toUpperCase(Locale.ROOT);
107	        return hex.length() % 2 == 0 ? hex : "0" + hex;
108	    }
109	
110	    // The ALB appends the address it saw to the end, so earlier entries are whatever the client sent.
111	    private String lastForwardedFor(HttpHeaders headers) {
112	        List<String> entries = headers.getOrEmpty(names.forwardedFor()).stream()
113	                .flatMap(line -> Stream.of(line.split(",", -1)))
114	                .map(String::trim)
115	                .toList();
